print('packsquash-automator V1.1')
import base64,os,shutil,subprocess,sys,tkinter as tk,atexit
try:import ctypes
except Exception as e:print(f'🔴 {e}')
from tkinter import filedialog

if getattr(sys,'frozen',False):SCRIPT_DIR=os.path.dirname(sys.executable)
else:SCRIPT_DIR=os.path.dirname(os.path.abspath(__file__))
WORK_DIR=os.path.join(SCRIPT_DIR,'packsquash_spec')
EXE_PATH=os.path.join(WORK_DIR,'packsquash.exe')
TOML_PATH=os.path.join(WORK_DIR,'config.toml')

def OnExit():
    shutil.rmtree(WORK_DIR,ignore_errors=True)
atexit.register(OnExit)

def ask(question):
    while 1:
        ans=input(f'{question} (Y/N): ').strip().lower()
        if ans in('y','yes'):return True
        if ans in('n','no'):return False

def fail(message):
    print(f'🔴 {message}')
    input('<< ')
    sys.exit(1)
def ok(message):print(f'🟢 {message}')

try:
    if not ctypes.windll.shell32.IsUserAnAdmin():
        if not ask('Compiler is running without admin permissions. Continue anyway?'):
            try:
                script=os.path.abspath(__file__)
                ctypes.windll.shell32.ShellExecuteW(None,'runas',sys.executable,f'"{script}"',None,1)
            except Exception:print('🔴 Unable to elevate to admin.')
            sys.exit(0)
except Exception:print('🔴 Failed to check admin status via ctypes.')
ICO_B64=(b'')

root=tk.Tk()
root.withdraw()
root.wm_attributes('-topmost', True)
icon=tk.PhotoImage(data=ICO_B64)
root.iconphoto(True,icon)
folder=filedialog.askdirectory(title='Select your resource pack folder')
root.destroy()

if not folder:fail('A folder is required.')
if not os.access(folder,os.R_OK):fail(f'Missing read permission for "{folder}".')
ok(f'"{folder}" chosen')

OUT_PATH=os.path.join(SCRIPT_DIR,f'{os.path.basename(folder).lower().replace(' ','-')}.zip')

try:
    shutil.rmtree(WORK_DIR,ignore_errors=True)
    os.makedirs(WORK_DIR)
    ok(f'Work directory at "{WORK_DIR}"')
except Exception as e:fail(f'Could not create work directory: {e}')

EXE_B64=(b'"),binary=')

try:
    with open(EXE_PATH,'wb')as f:f.write(base64.b64decode(EXE_B64))
    ok('packsquash.exe written')
except Exception as e:fail(f'Could not write executable: {e}')
folder_fwd=folder.replace('\\','/')
out_fwd=OUT_PATH.replace('\\','/')

TOML=f'''pack_directory = "{folder_fwd}"
output_file_path = "{out_fwd}"
zip_compression_iterations = 255
recompress_compressed_files = true

["**/*?.txt"]
force_include = true

["assets/**"]
force_include = true

["data/**"]
force_include = true

["META-INF/**"]
force_include = true

["**.json"]
force_include = true
'''

try:
    with open(TOML_PATH, 'w')as f:f.write(TOML)
    ok('config.toml written')
except Exception as e:fail(f'Could not write config: {e}')
print('Running PackSquash...')
try:
    result=subprocess.run([EXE_PATH, TOML_PATH])
    if result.returncode==0:ok(f'Done! Output: "{OUT_PATH}"')
    else:print(f'🔴 PackSquash exited with code {result.returncode}')
except PermissionError:
    fail(
        'Permission denied when launching the executable.\n'
        '   Windows may be blocking execution from this directory.\n'
        '   Try running as administrator.'
    )
except Exception as e:fail(f'Failed to launch PackSquash: {e}')
input('<< ')
